fun main() {
    println(Math.max(3, 9) + Math.min(2, 8))
    println(Math.abs(-5) + Math.abs(-2.5))
    println(Math.pow(2.0, 8.0))
    println(Math.sqrt(144.0))
    println(Math.floorMod(-7, 3) to Math.floorDiv(-7, 2))
    println(Math.round(2.5) to Math.round(-2.5) to Math.round(1.4))
    println(Math.floor(-1.1) to Math.ceil(-1.9))
    println(Math.hypot(3.0, 4.0))
    println(Math.PI > 3.14)
    println(Math.toDegrees(Math.PI))
    println(Math.signum(-8.0))
    println(Integer.parseInt("123") + Integer.valueOf(7))
    println(Integer.toBinaryString(10))
    println(Integer.toBinaryString(-1))
    println(Integer.toHexString(255) + Integer.toHexString(-256))
    println(Integer.toOctalString(64))
    println(Integer.bitCount(255) + Integer.numberOfTrailingZeros(8))
    println(Integer.MAX_VALUE)
    println(Integer.compare(3, 5))
    println(Integer.parseInt("-ff", 16))
    println(Integer.toString(255, 2))
    println(Integer.reverse(1))
    println(Integer.highestOneBit(100))
    println(Math.log10(1000.0) + Math.log(Math.E))
    println(Math.atan2(1.0, 1.0))
    println(Math.cbrt(27.0))
    try { Math.addExact(Int.MAX_VALUE, 1) } catch (e: ArithmeticException) { println(e.message) }
    try { Math.toIntExact(1L shl 40) } catch (e: ArithmeticException) { println(e.message) }
    println(Math.multiplyExact(46340, 46340))
}
